import { beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({
  user: vi.fn(),
  clear: vi.fn(),
  revalidate: vi.fn(),
}));
vi.mock("@/lib/session", () => ({ requireUser: mocks.user }));
vi.mock("@/lib/history", () => ({ clearCompletedHistory: mocks.clear }));
vi.mock("next/cache", () => ({ revalidatePath: mocks.revalidate }));
import { deleteHistory } from "@/lib/history-actions";

describe("delete history action", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    mocks.user.mockResolvedValue({ id: "owner" });
  });
  it("authenticates before deleting", async () => {
    mocks.user.mockRejectedValue(new Error("Authentication required"));
    await expect(deleteHistory()).rejects.toThrow("Authentication required");
    expect(mocks.clear).not.toHaveBeenCalled();
  });
  it("uses only the session owner and revalidates affected pages", async () => {
    mocks.clear.mockResolvedValue(2);
    expect(await deleteHistory()).toMatchObject({ ok: true, cleared: 2 });
    expect(mocks.clear).toHaveBeenCalledWith("owner");
    expect(mocks.revalidate.mock.calls.flat()).toEqual([
      "/settings",
      "/history",
      "/compose",
      "/contacts",
    ]);
  });
  it("handles an empty history", async () => {
    mocks.clear.mockResolvedValue(0);
    expect(await deleteHistory()).toEqual({
      ok: true,
      cleared: 0,
      message: "No completed history to delete.",
    });
  });
  it("does not expose database errors or report success after failure", async () => {
    mocks.clear.mockRejectedValue(new Error("Private database details"));
    expect(await deleteHistory()).toEqual({
      ok: false,
      message: "Could not delete history. Please try again.",
    });
    expect(mocks.revalidate).not.toHaveBeenCalled();
  });
});
